/**
 * Issue business rules: authorization, per-project issue quota, numbering, status transitions and the events every other concern reacts to.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, assertNotArchived
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import {
  actorEnvelope,
  issueResource,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  AssignIssueInput,
  ChangeIssueStatusInput,
  CreateIssueInput,
  IssueFilterInput,
  MoveIssueInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import type { IssueId, OrgId, Page, ProjectId } from "@/types/common";
import type { Issue, IssueBoardColumn, IssueWithRelations } from "@/types/issue";
import type { Actor } from "@/types/member";

/**
 * Creates an issue after four gates: tenant scope, the `issue:create`
 * permission, a live parent project and the plan's per-project issue quota.
 * Only then is a number allocated and `issue.created` published — everything
 * reactive (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number);

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });

  return issue;
}

export async function updateIssue(
  actor: Actor,
  input: UpdateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.updateIssue(input);

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: Object.keys(input).filter(
      (key) => key !== "orgId" && key !== "issueId",
    ),
  });

  return after;
}

/** Status transitions are an `issue:update`, not a separate permission. */
export async function changeIssueStatus(
  actor: Actor,
  input: ChangeIssueStatusInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (before.status === input.status) return before;

  const after = await issueRepo.setIssueStatus(
    input.orgId,
    input.issueId,
    input.status,
  );

  await emit("issue.status_changed", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    from: before.status,
    to: after.status,
  });

  return after;
}

/**
 * Assignment has its own permission because a member may reassign work they
 * do not otherwise own. Un-assigning publishes `issue.updated` instead, since
 * `issue.assigned` carries a non-null assignee by contract.
 */
export async function assignIssue(
  actor: Actor,
  input: AssignIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:assign", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.setIssueAssignee(
    input.orgId,
    input.issueId,
    input.assigneeId,
  );

  if (input.assigneeId === null) {
    await emit("issue.updated", {
      ...actorEnvelope(actor),
      issueId: after.id,
      projectId: after.projectId,
      changedFields: ["assigneeId"],
    });
    return after;
  }

  await emit("issue.assigned", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    previousAssigneeId: before.assigneeId,
    assigneeId: input.assigneeId,
  });

  return after;
}

export async function archiveIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const archived = await issueRepo.archiveIssue(orgId, issueId);

  await emit("issue.archived", {
    ...actorEnvelope(actor),
    issueId: archived.id,
    projectId: archived.projectId,
  });

  return archived;
}

/**
 * Board drag-and-drop. The index is presentation-only — the board renders by
 * `updated_at` — so a move is a status change plus a touch.
 */
export async function moveIssue(
  actor: Actor,
  input: MoveIssueInput,
): Promise<Issue> {
  return changeIssueStatus(actor, {
    orgId: input.orgId,
    issueId: input.issueId,
    status: input.toStatus,
  });
}

export async function getIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueWithRelations> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const labels = await labelRepo.listLabelsForIssues(orgId, [issue.id]);

  return {
    issue,
    labels: labels[issue.id] ?? [],
    commentCount: await commentRepo.countComments(orgId, issue.id),
    attachmentCount: (await attachmentRepo.listAttachments(orgId, issue.id))
      .length,
  };
}

export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  assertOrgScope(actor, input.orgId);
  // A cross-project list is an org-wide read; per-project visibility is
  // enforced when the caller opens an individual issue.
  assertCan(actor, "issue:read", orgResource(input.orgId));
  return issueRepo.listIssues(input);
}

export async function getBoard(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueBoardColumn[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "issue:read", projectResource(project));

  return issueRepo.listBoardColumns(orgId, projectId);
}
/**
 * Audit-log writer and reader. Subscribes to the whole event bus and records one row per domain event.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, toCsv
 */
import { toCsv } from "@/lib/csv";
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { activityResource } from "./_support";
import type { ActivityFilterInput, ExportActivityInput } from "@/schemas/activity";
import type {
  ActivityAction,
  ActivityEvent,
  ActivityGroup,
  ActivitySubjectKind,
} from "@/types/activity";
import type { OrgId, Page, ProjectId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

export type ActivityRecordInput = {
  actorId: UserId | null;
  subjectKind: ActivitySubjectKind;
  subjectId: string;
  projectId: ProjectId | null;
  summary: string;
  metadata?: Readonly<Record<string, string | number | boolean | null>>;
};

/** Columns of the audit-log CSV export, in the order the file lists them. */
const EXPORT_COLUMNS = [
  "occurredAt",
  "action",
  "actorId",
  "subjectKind",
  "subjectId",
  "summary",
] as const;

/**
 * Appends one audit row. Deliberately takes no `Actor`: the writer is usually
 * an event handler running outside a request, and the row's `actorId` comes
 * from the event payload rather than from an authenticated principal.
 */
export async function record(
  orgId: OrgId,
  action: ActivityAction,
  input: ActivityRecordInput,
): Promise<ActivityEvent> {
  return activityRepo.insertActivity({
    orgId,
    action,
    actorId: input.actorId,
    subjectKind: input.subjectKind,
    subjectId: input.subjectId,
    projectId: input.projectId,
    summary: input.summary,
    metadata: input.metadata ?? {},
    occurredAt: toIsoTimestamp(new Date()),
  });
}

export async function listActivity(
  actor: Actor,
  input: ActivityFilterInput,
): Promise<Page<ActivityEvent>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "activity:read", activityResource(input.orgId));
  return activityRepo.listActivity(input);
}

/** Groups a feed page by calendar day, newest day first. */
export function groupByDay(
  events: readonly ActivityEvent[],
): readonly ActivityGroup[] {
  const byDay = new Map<string, ActivityEvent[]>();

  for (const event of events) {
    const day = event.occurredAt.slice(0, 10);
    const bucket = byDay.get(day) ?? [];
    bucket.push(event);
    byDay.set(day, bucket);
  }

  return [...byDay.entries()]
    .sort(([a], [b]) => (a < b ? 1 : -1))
    .map(([day, dayEvents]) => ({ day, events: dayEvents }));
}

/**
 * CSV (or JSON) export of the audit log. Gated twice: on `activity:export`
 * for the role, and on the `csv_export` flag for the plan.
 */
export async function exportActivity(
  actor: Actor,
  input: ExportActivityInput,
): Promise<string> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "activity:export", activityResource(input.orgId));

  const org = await orgRepo.findOrgById(input.orgId);
  const flagEnabled = isEnabled("csv_export", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  if (input.format === "csv" && !flagEnabled) {
    throw new Error("CSV export is not included in this plan");
  }

  const page = await activityRepo.listActivity({
    orgId: input.orgId,
    since: input.since,
    until: input.until,
    limit: 100,
    cursor: null,
  });

  if (input.format === "json") {
    return JSON.stringify(page.items, null, 2);
  }

  return toCsv(
    page.items.map((event) => ({
      occurredAt: event.occurredAt,
      action: event.action,
      actorId: event.actorId,
      subjectKind: event.subjectKind,
      subjectId: event.subjectId,
      summary: event.summary,
    })),
    [...EXPORT_COLUMNS],
  );
}

/**
 * Attaches one handler per audited event type. Called once from
 * `event-registry`; the returned function detaches all of them, which is what
 * the test suite uses to keep the bus clean between cases.
 */
export function registerActivityListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("project.created", (payload) =>
      record(payload.orgId, "project.created", {
        actorId: payload.actorId,
        subjectKind: "project",
        subjectId: payload.projectId,
        projectId: payload.projectId,
        summary: `Created project ${payload.name}`,
      }).then(() => undefined),
    ),
    subscribe("project.archived", (payload) =>
      record(payload.orgId, "project.archived", {
        actorId: payload.actorId,
        subjectKind: "project",
        subjectId: payload.projectId,
        projectId: payload.projectId,
        summary: `Archived project with ${payload.issuesArchived} issues`,
      }).then(() => undefined),
    ),
    subscribe("issue.created", (payload) =>
      record(payload.orgId, "issue.created", {
        actorId: payload.actorId,
        subjectKind: "issue",
        subjectId: payload.issueId,
        projectId: payload.projectId,
        summary: `Created issue "${payload.title}"`,
        metadata: { priority: payload.priority },
      }).then(() => undefined),
    ),
    subscribe("issue.status_changed", (payload) =>
      record(payload.orgId, "issue.status_changed", {
        actorId: payload.actorId,
        subjectKind: "issue",
        subjectId: payload.issueId,
        projectId: payload.projectId,
        summary: `Status ${payload.from} → ${payload.to}`,
        metadata: { from: payload.from, to: payload.to },
      }).then(() => undefined),
    ),
    subscribe("issue.assigned", (payload) =>
      record(payload.orgId, "issue.assigned", {
        actorId: payload.actorId,
        subjectKind: "issue",
        subjectId: payload.issueId,
        projectId: payload.projectId,
        summary: `Assigned to ${payload.assigneeId}`,
      }).then(() => undefined),
    ),
    subscribe("comment.created", (payload) =>
      record(payload.orgId, "comment.created", {
        actorId: payload.actorId,
        subjectKind: "comment",
        subjectId: payload.commentId,
        projectId: null,
        summary: `Commented on issue ${payload.issueId}`,
      }).then(() => undefined),
    ),
    subscribe("member.invited", (payload) =>
      record(payload.orgId, "member.invited", {
        actorId: payload.actorId,
        subjectKind: "member",
        subjectId: payload.email,
        projectId: null,
        summary: `Invited ${payload.email} as ${payload.role}`,
      }).then(() => undefined),
    ),
    subscribe("member.role_changed", (payload) =>
      record(payload.orgId, "member.role_changed", {
        actorId: payload.actorId,
        subjectKind: "member",
        subjectId: payload.memberId,
        projectId: null,
        summary: `Role ${payload.from} → ${payload.to}`,
      }).then(() => undefined),
    ),
    subscribe("billing.plan_changed", (payload) =>
      record(payload.orgId, "billing.plan_changed", {
        actorId: payload.actorId,
        subjectKind: "subscription",
        subjectId: payload.orgId,
        projectId: null,
        summary: `Plan ${payload.from} → ${payload.to}`,
      }).then(() => undefined),
    ),
  ];

  return () => {
    for (const off of offs) off();
  };
}

