    for (const event of unassigned) {
      expect(event).toMatchObject({
        actorId: removalTenant.userIds.owner,
        previousAssigneeId: removalTenant.userIds.viewer,
        projectId: removalTenant.project.id,
      });
    }

    const reload = (id: typeof first.id) =>
      issueRepo.findIssueById(removalTenant.org.id, id);
    expect((await reload(first.id))?.assigneeId).toBeNull();
    expect((await reload(second.id))?.assigneeId).toBeNull();
    expect((await reload(archived.id))?.assigneeId).toBe(
      removalTenant.userIds.viewer,
    );
    expect((await reload(someoneElses.id))?.assigneeId).toBe(
      removalTenant.userIds.admin,
    );
  });
});

